input.new_text:
// 轴标签：按方位对齐（右侧左对齐、左侧右对齐、上下居中），保证文字始终在雷达外
var labelR = R + pl(10), lsize = pl(19);
for (var d = 0; d < n; d++) {
  var a = (-90 + d * (360 / n)) * Math.PI / 180;
  var ca = Math.cos(a), sa = Math.sin(a);
  // 估算文字宽度：CJK 按整字宽，拉丁字符按 0.55 字宽
  var tw = 0;
  for (var c = 0; c < labels[d].length; c++) {
    tw += labels[d].charCodeAt(c) > 0x2E7F ? lsize : lsize * 0.55;
  }
  var px = rcx + labelR * ca, py = rcy + labelR * sa;
  var lx, ly;
  if (ca > 0.3) lx = px + pl(4);           // 右侧：从锚点向外延伸
  else if (ca < -0.3) lx = px - tw - pl(4); // 左侧：整体外推
  else lx = px - tw / 2;                    // 正上/正下：水平居中
  if (sa < -0.3) ly = py - lsize;           // 上方：抬到雷达顶点之上
  else if (sa > 0.3) ly = py + pl(2);       // 下方：压到雷达底点之下
  else ly = py - lsize / 2;                 // 水平方向：垂直居中
  cv.drawText({ x: Math.round(lx), y: Math.round(ly), text: labels[d], text_size: lsize, color: 0x6A4A28 });
}

