   302→export function diagnosePulse(metrics) {
   303→  const { 
   304→    sdnn = 0, sdann = 0, restingHr = 0, avgHr = 0, mean_hr = 0, 
   305→    hrStability = 0, sdnnSegments = [], stress = 0, sleepScore = 0, 
   306→    hrReserve = 0, patternEntropy = 0, lfRms = 0, vlfRms = 0,
   307→    rsaEiRatio = 0
   308→  } = metrics;
   309→
   310→  // 使用新提取的非线性指标 (Pattern Entropy) 和 频域 (LF/VLF RMS) 修正节律和宽度
   311→  let adjustedSdnn = sdnn;
   312→  let adjustedStress = stress;
   313→
   314→  if (patternEntropy > 0) {
   315→    if (patternEntropy < 1.0) adjustedSdnn = Math.max(0, adjustedSdnn - 10);
   316→    else if (patternEntropy > 2.5) adjustedSdnn = Math.min(100, adjustedSdnn + 10);
   317→  }
   318→
   319→  if (lfRms > 0 && vlfRms > 0) {
   320→    const lfVlfRatio = lfRms / vlfRms;
   321→    if (lfVlfRatio > 2.0) adjustedStress = Math.min(100, adjustedStress + 15);
   322→    else if (lfVlfRatio < 0.5) adjustedStress = Math.max(0, adjustedStress - 15);
   323→  }
   324→
   325→const dimensions = {
   326→    rate:     classifyRate(restingHr || avgHr || mean_hr),
   327→    rhythm:   classifyRhythm(adjustedSdnn),
   328→    strength: classifyStrength(sdann, hrReserve),
   329→    width:    classifyWidth(hrStability, adjustedStress),
   330→    tension:  classifyTension(adjustedStress, adjustedSdnn),
   331→    rsa:      classifyRsa(rsaEiRatio)
   332→  };
   333→
   334→  let segmentTrend = 'stable';
   335→  if (sdnnSegments.length >= 3) {
   336→    const first = sdnnSegments.slice(0, Math.ceil(sdnnSegments.length / 2));
   337→    const second = sdnnSegments.slice(Math.ceil(sdnnSegments.length / 2));
   338→    const avgFirst = first.reduce((a, b) => a + b, 0) / first.length;
   339→    const avgSecond = second.reduce((a, b) => a + b, 0) / second.length;
   340→    if (avgFirst > 0 && avgSecond / avgFirst > 1.1) segmentTrend = 'relaxing';
   341→    else if (avgFirst > 0 && avgSecond / avgFirst < 0.9) segmentTrend = 'tiring';
   342→  }
   343→
   344→  const mainPulse = matchPulseType(dimensions, metrics);
   345→  const constitution = assessConstitution(dimensions, mainPulse, metrics);
   346→const organAnalysis = analyzeOrgans(dimensions, mainPulse, metrics);
   347→  const recommendations = generateRecommendations(dimensions, constitution, organAnalysis);
   348→
   349→  return { mainPulse, dimensions, constitution, organAnalysis, recommendations, segmentTrend, timestamp: Date.now() };
   350→}
