Page({
  state: {
    count: 6,
    arcWidgets: [],
    arcTargets: [],
    animated: {},
    monitorTimer: null,
    dims: null,   // 真实诊断构造的六维数组；null = 无测量数据
  },

  onInit() {
    this._built = false;
    var self = this;
    var storage = new HrvStorageManager();
    storage.init(function () {
      storage.getTodayData(function (todayData) {
        if (todayData && todayData.length > 0) {
          var latest = todayData[todayData.length - 1];
          if (latest && latest.metrics && latest.metrics.sdnn > 0) {
            var diag = diagnosePulse(latest.metrics);
            if (diag && diag.dimensions) {
              self.state.dims = DIM_KEYS.map(function (k) {
                var d = diag.dimensions[k] || { score: 0, label: '' };
                return { key: k, score: d.score, label: d.label, tint: DIM_TINTS[k], descKey: DIM_DESC_KEYS[k] };
              });
            }
          }
        }
        self.build();
      });
    });
  },

  build() {
    if (this._built) return;
    this._built = true;

    var dev = getDeviceInfo();
    var W = dev.width;
    var H = dev.height;

    setStatusBarVisible(false);

    // 无测量数据：不展示任何分值/弧形，仅提示先把脉
    if (!this.state.dims) {
      createWidget(widget.IMG, { x: pw(0), y: 0, w: pl(480), h: H, src: 'bg/list1.png' });
      createWidget(widget.TEXT, {
        x: pl(40), y: 0, w: W - pl(80), h: H,
        text_size: pl(30), color: C.text,
        text: getText('no_records_today'),
        align_h: align.CENTER_H, align_v: align.CENTER_V,
        text_style: text_style.WRAP,
      });
      return;
    }

    setScrollMode({
      mode: SCROLL_MODE_SWIPER,
      options: { height: H, count: this.state.count },
    });

    // 背景
    for (var i = 0; i < this.state.count; i++) {
      createWidget(widget.IMG, {
        x: pw(0), y: H * i, w: pl(480), h: H,
        src: 'bg/list1.png',
      });
    }

    var self = this;

    this.state.dims.forEach(function (item, idx) {
      var vc = createWidget(widget.VIEW_CONTAINER, {
        x: 0, y: 0, w: W, h: H,
        scroll_enable: 0,
        page: idx,
      });

      var fgArc = drawDimPage(vc, item, idx, W, H);
      self.state.arcWidgets.push(fgArc);
      self.state.arcTargets.push(scoreToArcAngle(item.score));
    });

    this._startMonitor();
  },

