// 控件建在滚动容器 vc 内
function _drawPulseCard(vc, x, y, cardW, shape, lineColor, hasData) {
  var cardH = pl(150);
  var padX = pl(15), waveTop = pl(6), waveH = pl(138);

  vc.createWidget(widget.FILL_RECT, { x: x, y: y, w: cardW, h: cardH, radius: pl(32), color: 0xCDC0A5 });


  // Canvas：竖向界格 + 中轴基线（脉诊仪质感，淡雅不抢眼）
  var cv = vc.createWidget(widget.CANVAS, { x: x, y: y, w: cardW, h: cardH });
  cv.setPaint({ color: 0xC6B896, line_width: 1 });
  for (var g = 0; g <= 4; g++) {
    var gx = padX + Math.round(g * (pl(360) / 4));
    cv.drawLine({ x1: gx, y1: waveTop + pl(6), x2: gx, y2: waveTop + waveH - pl(6), color: 0xC6B896 });
  }
  var baseY = waveTop + Math.round(waveH / 2);
  cv.drawLine({ x1: padX, y1: baseY, x2: padX + pl(360), y2: baseY, color: 0xB0A176 });

  // 回声线（浅色下移，制造层次/余韵）
  if (hasData) {
    var echo = vc.createWidget(widget.GRADKIENT_POLYLINE, { x: x + padX, y: y + waveTop + pl(6), w: pl(360), h: waveH, line_color: 0xDCC58C, line_width: pl(3) });
    echo.clear();
    echo.addLine(shape);
  }
  // 主脉线
  var ln = vc.createWidget(widget.GRADKIENT_POLYLINE, { x: x + padX, y: y + waveTop, w: pl(360), h: waveH, line_color: hasData ? lineColor : 0xB0A176, line_width: pl(5) });

