build() {
  if (this._built) {
    logger.log(`[Perf] build() SKIP (already built) — caller may be framework re-entry`);
    return;
  }
  var _t = Date.now();
  var dev = getDeviceInfo();
  var W = dev.width;
  var H = dev.height;
  setStatusBarVisible(false);

  // --- 固定背景（单图一屏，不随内容滚动，避免多张大图参与滚动渲染）---
  if (!this._bgCreated) {
    createWidget(widget.IMG, { x: pw(0), y: ph(0), w: pl(480), h: pl(480), src: "Bg.png" });
    this._bgCreated = true;
  }

  // --- 全屏滚动容器：所有内容控件挂在容器内，滚动由容器接管 ---
  // 重建（onShow 新数据）时整树删除旧容器，避免控件堆叠泄漏
  if (this.state.container) {
    deleteWidget(this.state.container);
    this.state.container = null;
  }
  var vc = createWidget(widget.VIEW_CONTAINER, { x: 0, y: 0, w: W, h: H, scroll_enable: 1 });
  this.state.container = vc;

  // --- 环形时钟 ---
  this.state.timeText = vc.createWidget(widget.TEXT, { x: 0, y: 2, w: W, h: W, text_size: pl(32), color: C.clock, text: "--:--", align_h: align.CENTER_H, start_angle: -80, end_angle: 80 });

  var diag = this.state.lastDiagnosis;
  var hasData = diag && diag.mainPulse;
  var mp = hasData ? diag.mainPulse : { type: 'flat', name: '--', nature: 'neutral', description: '暂无脉象数据，请先进行把脉' };
  var pc = hasData ? (mp.nature === 'yang' ? C.gold : mp.nature === 'yin' ? 0x60B0E0 : C.good) : C.sub;

  var cardW = pl(390);
  var cX = Math.round((W - cardW) / 2);

  // --- 脉名 ---
  var Y = pl(64);
  vc.createWidget(widget.TEXT, { x: 0, y: Y, w: W, h: pl(58), text_size: pl(46), color: pc, text: mp.name, align_h: align.CENTER_H });
  Y += pl(66);

  // --- 脉形图（宣纸界格 + 中轴基线 + 双线脉波，招牌视觉）---
  Y += _drawPulseCard(vc, cX, Y, cardW, _cachedPulseShape(mp.type), pc, hasData) + pl(14);
  logger.log(`[Perf] §时钟+脉名+脉形图 done — ${Date.now() - _t}ms`);

