     4→function normalizeLineText(text) {
     5→  return String(text || "").replace(/\r\n/g, "\n");
     6→}
     7→
     8→function stripInlineMarkdown(text) {
     9→  return String(text || "")
    10→    .replace(/\*\*\*(.*?)\*\*\*/g, "$1")
    11→    .replace(/___(.*?)___/g, "$1")
    12→    .replace(/\*\*(.*?)\*\*/g, "$1")
    13→    .replace(/__(.*?)__/g, "$1")
    14→    .replace(/\*(.*?)\*/g, "$1")
    15→    .replace(/_(.*?)_/g, "$1")
    16→    .replace(/`([^`]+)`/g, "$1");
    17→}
    18→
