    20→function parseMarkdownBlocks(text) {
    21→  const lines = normalizeLineText(text).split("\n");
    22→  const blocks = [];
    23→  let codeMode = false;
    24→  let codeBuffer = [];
    25→
    26→  lines.forEach((rawLine) => {
    27→    const line = rawLine.replace(/\s+$/, "");
    28→    const trimmed = line.trim();
    29→
    30→    if (trimmed.startsWith("```") && !codeMode) {
    31→      codeMode = true;
    32→      codeBuffer = [];
    33→      return;
    34→    }
    35→    if (trimmed.startsWith("```") && codeMode) {
    36→      blocks.push({ type: "code", text: codeBuffer.join("\n") });
    37→      codeMode = false;
    38→      return;
    39→    }
    40→    if (codeMode) {
    41→      codeBuffer.push(line);
    42→      return;
    43→    }
    44→
    45→    if (trimmed.length === 0) {
    46→      blocks.push({ type: "spacer" });
    47→      return;
    48→    }
    49→
    50→    const hrMatch = line.match(/^\s*([-*_])(?:\s*\1){2,}\s*$/);
    51→    const headingMatch = line.match(/^\s*(#{1,3})\s+(.*)$/);
    52→    const blockquoteMatch = line.match(/^\s*>\s?(.*)$/);
    53→    const listMatch = line.match(/^\s*(?:[-*]|\d+\.)\s+(.*)$/);
    54→
    55→    if (headingMatch) {
    56→      const level = headingMatch[1].length === 1 ? "heading1"
    57→        : headingMatch[1].length === 2 ? "heading2"
    58→        : "heading3";
    59→      blocks.push({ type: level, text: headingMatch[2] });
    60→    } else if (hrMatch) {
    61→      blocks.push({ type: "divider" });
    62→    } else if (blockquoteMatch) {
    63→      blocks.push({ type: "blockquote", text: blockquoteMatch[1] });
    64→    } else if (listMatch) {
    65→      blocks.push({ type: "list", text: listMatch[1] });
    66→    } else {
    67→      blocks.push({ type: "paragraph", text: line });
    68→    }
    69→  });
    70→
    71→  return blocks;
    72→}
    73→
    74→function getBlockStyle(type, baseSize) {
    75→  switch (type) {
    76→    case "heading1":
    77→      return { size: baseSize + pl(10), color: 0xffffff };
    78→    case "heading2":
    79→      return { size: baseSize + pl(6), color: 0xe8f8ff };
    80→    case "heading3":
    81→      return { size: baseSize + pl(4), color: 0xd9f4ff };
    82→    case "blockquote":
    83→      return { size: baseSize, color: 0xc8e8ff };
    84→    case "list":
    85→      return { size: baseSize, color: 0xfff7c4 };
    86→    case "code":
    87→      return { size: Math.max(baseSize - pl(2), pl(14)), color: 0xa6f2e5 };
    88→    case "divider":
    89→      return { size: baseSize, color: 0x8aa7c3 };
    90→    default:
    91→      return { size: baseSize, color: 0xdfefff };
    92→  }
    93→}
