    95→export function buildMarkdownLayout(text, maxWidth, baseSize) {
    96→  const blocks = parseMarkdownBlocks(text);
    97→  const items = [];
    98→  const blockSpacing = pl(8);
    99→  let offset = 0;
   100→
   101→  blocks.forEach((block, index) => {
   102→    if (block.type === "spacer") {
   103→      offset += pl(10);
   104→      return;
   105→    }
   106→
   107→    const style = getBlockStyle(block.type, baseSize);
   108→    let content = stripInlineMarkdown(String(block.text || "").trim());
   109→
   110→    if (block.type === "list") {
   111→      content = `• ${content}`;
   112→    }
   113→    if (block.type === "heading1") {
   114→      content = content.toUpperCase();
   115→    }
   116→
   117→    const layout = getTextLayout(content, {
   118→      text_size: style.size,
   119→      text_width: maxWidth,
   120→      wrapped: 1,
   121→    });
