   242→        const rr = valid.map(bpm => 60000 / bpm);
   243→        const segMeans = [];
   244→        for (let i = 0; i + 5 <= rr.length; i += 5) segMeans.push(rr.slice(i, i + 5).reduce((a, b) => a + b, 0) / 5);
   245→        if (segMeans.length >= 2) {
   246→          const m = segMeans.reduce((a, b) => a + b, 0) / segMeans.length;
   247→          sdann = parseFloat(Math.sqrt(segMeans.reduce((s, v) => s + Math.pow(v - m, 2), 0) / segMeans.length).toFixed(2));
   248→        }
   249→      }
   250→    }
   251→    if (typeof hr.getResting === 'function') { try { const r = hr.getResting(); if (r > 0) restingHr = Math.round(r); } catch (e) {} }
   252→  } catch (e) {}
   253→  try {
   254→    const st = new Stress();
   255→    const arr = st.getTodayByHour();
   256→    if (Array.isArray(arr) && arr.length > 0) {
   257→      const vv = arr.filter(v => typeof v === 'number' && v > 0);
   258→      if (vv.length > 0) stressVal = Math.round(vv.reduce((a, b) => a + b, 0) / vv.length);
   259→    }
   260→  } catch (e) {}
   261→  try {
   262→    const sl = new Sleep();
   263→    const info = sl.getInfo();
   264→    if (info && info.totalTime > 0) {
   265→      const m = info.totalTime;
   266→      if (m >= 420 && m <= 540) sleepScore = 10; else if (m >= 360) sleepScore = 8;
   267→      else if (m >= 300) sleepScore = 6; else if (m >= 240) sleepScore = 4; else sleepScore = 2;
   268→    }
   269→  } catch (e) {}
   270→  return { sdann, stressVal, sleepScore, hrReserve, restingHr };
   271→}
   272→
   273→// TCM 分段 SDNN + 心率稳定性
   274→function calcTcmMetrics(rr) {
   275→  if (!rr || rr.length < 2) return null;
   276→  const hrVals = rr.map(r => 60000 / r);
   277→  const hrMean = hrVals.reduce((a, b) => a + b, 0) / hrVals.length;
   278→  const hrStab = Math.sqrt(hrVals.reduce((s, v) => s + Math.pow(v - hrMean, 2), 0) / hrVals.length);
   279→  const segs = []; let acc = 0, srr = [];
   280→  for (let i = 0; i < rr.length; i++) {
   281→    acc += rr[i]; srr.push(rr[i]);
   282→    if (acc >= 60000 && srr.length >= 5) {
   283→      const sm = srr.reduce((a, b) => a + b, 0) / srr.length;
   284→      segs.push(+Math.sqrt(srr.reduce((s, r) => s + Math.pow(r - sm, 2), 0) / (srr.length - 1)).toFixed(2));
   285→      srr = []; acc = 0;
   286→    }
   287→  }
   288→  return { hrStability: +hrStab.toFixed(2), sdnnSegments: segs, rrCount: rr.length };
   289→}
   290→
   291→// RSA: 从 BPM 序列提取 E/I ratio (呼吸-心率耦合指数)
   292→// 呼吸使心率周期性起伏（吸气升、呼气降）。去趋势后取局部峰=吸气相心率、
   293→// 谷=呼气相心率，E/I ≈ 平均峰值 / 平均谷值。峰谷用其在原序列的真实索引取回 BPM。
   294→function calcRsaEiRatio(bpmSeq) {
   295→  if (!bpmSeq || bpmSeq.length < 30) return 0;
   296→
   297→  // 去趋势：减去 ±5 窗口移动均值，保留呼吸尺度的波动
   298→  const detr = [];
   299→  for (let i = 0; i < bpmSeq.length; i++) {
   300→    let sum = 0, cnt = 0;
   301→    for (let j = Math.max(0, i - 5); j <= Math.min(bpmSeq.length - 1, i + 5); j++) { sum += bpmSeq[j]; cnt++; }
   302→    detr.push(bpmSeq[i] - sum / cnt);
   303→  }
   304→
   305→  // 在去趋势信号上找局部峰/谷，用真实索引取回对应 BPM
   306→  const peaks = [], troughs = [];
   307→  for (let i = 1; i < detr.length - 1; i++) {
   308→    if (detr[i] > detr[i - 1] && detr[i] >= detr[i + 1]) peaks.push(bpmSeq[i]);
   309→    else if (detr[i] < detr[i - 1] && detr[i] <= detr[i + 1]) troughs.push(bpmSeq[i]);
   310→  }
   311→  if (peaks.length < 2 || troughs.length < 2) return 0;
   312→
   313→  const avgPeak = peaks.reduce((a, b) => a + b, 0) / peaks.length;
   314→  const avgTrough = troughs.reduce((a, b) => a + b, 0) / troughs.length;
   315→  if (avgTrough <= 0) return 0;
   316→  return +(avgPeak / avgTrough).toFixed(3);
   317→}
   318→
   319→// =============================================================================
   320→Page({
