   327→    timeText: null,
   328→    ringWidget: null,
   329→    countdownText: null,
   330→    bpmText: null,
   331→    startBtn: null,
   332→
   333→    countdownTimer: null,
   334→    ringTimer: null,
   335→    clockTimer: null,
   336→  },
   337→
   338→  onInit() {
   339→    this.state.hrvStorage = new HrvStorageManager();
   340→    this.state.hrvStorage.init(() => {});
   341→    this.state.allDay = fetchAllDayMetrics();
   342→  },
   343→
   344→  build() {
   345→    const { width, height } = getDeviceInfo();
   346→    setPageBrightTime({ brightTime: 600000 });
   347→    pauseDropWristScreenOff({ duration: DURATION_SEC * 1000 + 5000 });
   348→    setStatusBarVisible(false);
   349→    createWidget(widget.IMG, { x: pw(0), y: ph(0), w: pl(480), h: pl(480), src: "Mbg.png" });
   350→
   351→    this.state.timeText = createWidget(widget.TEXT, {
   352→      x: 0, y: 5, w: width, h: width,
   353→      text_size: pl(35), color: C.clock, text: "00:00",
   354→      align_h: align.CENTER_H, start_angle: -80, end_angle: 80
   355→    });
   356→    this._updateClock();
   357→    this.state.clockTimer = setInterval(() => this._updateClock(), 60000);
   358→
   359→    const ringR = pl(130);
   360→    const ringX = (width - ringR * 2) / 2;
   361→    const ringY = height / 2 - ringR - pl(10);
   362→    const ringW = pl(18);
   363→
   364→    createWidget(widget.ARC, {
   365→      x: ringX, y: ringY, w: ringR * 2, h: ringR * 2,
   366→      start_angle: 0, end_angle: 360,
   367→      color: C.ringBg, line_width: ringW,
   368→    });
   369→
   370→    this.state.ringWidget = createWidget(widget.ARC, {
   371→      x: ringX, y: ringY, w: ringR * 2, h: ringR * 2,
   372→      start_angle: 0, end_angle: 270,
   373→      color: C.gold, line_width: ringW, line_cap: 'round',
   374→    });
   375→
   376→    this.state.countdownText = createWidget(widget.TEXT, {
   377→      x: ringX, y: ringY, w: ringR * 2, h: ringR * 2,
   378→      text_size: pl(48), color: C.countdown, text: "3:00",
   379→      align_h: align.CENTER_H, align_v: align.CENTER_V,
   380→    });
   381→
   382→    this.state.bpmText = createWidget(widget.TEXT, {
   383→      x: 0, y: height / 2 + ringR + pl(20), w: width, h: pl(35),
   384→      text_size: pl(26), color: C.bpm, text: "",
   385→      align_h: align.CENTER_H,
   386→    });
   387→
   388→    this.state.startBtn = createWidget(widget.BUTTON, {
   389→      x: (width - pl(200)) / 2, y: height - pl(100), w: pl(200), h: pl(80),
   390→      radius: pl(40),
   391→      normal_color: C.btnBg, press_color: C.btnPress,
   392→      text: getText("start_pulse"), text_size: pl(30), color: C.gold,
   393→      click_func: () => { if (!this.state.isMeasuring) this.start(); }
   394→    });
