/**
 * settings.js — 设置页
 *
 * 核心功能：无感测量 —— 用户设定一个每日时间（建议起床前 30~60 分钟），
 * 到点由系统闹钟自动唤醒 page/measurement 完成一次把脉，全程无需操作。
 * 提示文案用 markdown-renderer 渲染。
 */

import { createWidget, widget, align, prop } from "@zos/ui";
import { set as setAlarm, cancel as cancelAlarm, REPEAT_DAY } from '@zos/alarm';
import { Storage } from '../utils/storage';
import { getDeviceInfo } from "@zos/device";
import { showToast } from '@zos/interaction';
import { push } from "@zos/router";
import { pw, ph, pl } from "../utils/zaui";
import { getText } from '@zos/i18n';
import { setStatusBarVisible } from '@zos/ui';
import { buildMarkdownLayout, renderMarkdown } from '../utils/markdown-renderer';

const SYSTEM_FILE = 'system.json';
const SETTINGS_FILE = 'settings.json';
// 闹钟唤醒测量页；param 由 app.js onCreate 接收，标记本次为无感自动测量
const AUTO_MEASURE_PAGE_URL = 'page/measurement';
const AUTO_MEASURE_PARAM = 'auto_measure';

// M3 Color Palette (Dark Theme)
const COLORS = {
  SURFACE: 0x000000,
  SURFACE_CONTAINER: 0x2b2930, // Dark Grey Card
  SURFACE_CONTAINER_HIGH: 0x36343b,
  PRIMARY: 0xd0bcff, // Light Purple
  ON_PRIMARY: 0x381e72,
  ON_SURFACE: 0xe6e0e9, // White-ish text
  ON_SURFACE_VARIANT: 0xcac4d0, // Grey text
  OUTLINE: 0x938f99,
  ERROR: 0xf2b8b5
};

let mainSwitch;
let wakeTimeText;
let timeTextWidget;
let timeInterval = null;

// 计算「今天/明天 HH:MM」的下一次触发时间（UTC 秒），供 @zos/alarm time 字段使用
function nextOccurrenceTs(hour, minute) {
  const now = new Date();
  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), hour, minute, 0);
  if (t.getTime() <= now.getTime()) t.setDate(t.getDate() + 1);
  return Math.floor(t.getTime() / 1000);
}

function fmtTime(hour, minute) {
  return `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
}

Page({
  state: {
    settings: {
      isEnabled: false,
      wakeHour: 7,     // 每日自动测量时间（默认 07:00）
      wakeMinute: 0,
    },
    alarmId: 0,
    isActivated: false
  },

  onInit() {
    Storage.get(SETTINGS_FILE, (err, userSettings) => {
      if (userSettings && userSettings.hrv) {
        const s = userSettings.hrv;
        if (typeof s.isEnabled === 'boolean') this.state.settings.isEnabled = s.isEnabled;
        if (typeof s.wakeHour === 'number') this.state.settings.wakeHour = s.wakeHour;
        if (typeof s.wakeMinute === 'number') this.state.settings.wakeMinute = s.wakeMinute;
      }

      Storage.get(SYSTEM_FILE, (err, config) => {
        if (config) {
          if (config.alarm_id) this.state.alarmId = parseInt(config.alarm_id);
          this.state.isActivated = config.activation_status === 'activated';
        }

        this.build();
        this.startTimeTicker();
      });
    });
  },

  startTimeTicker() {
    if (timeInterval) clearInterval(timeInterval);
    const updateTime = () => {
      if (timeTextWidget) {
        const now = new Date();
        const hours = now.getHours().toString().padStart(2, "0");
        const minutes = now.getMinutes().toString().padStart(2, "0");
        timeTextWidget.setProperty(prop.TEXT, `${hours}:${minutes}`);
      }
    };
    updateTime();
    timeInterval = setInterval(updateTime, 1000);
  },

  build() {
    const { width } = getDeviceInfo();
    setStatusBarVisible(false);

    // Initial Y offset (account for round screen top)
    let y = pl(20);

    // 1. Time Display (Curved text at top)
    timeTextWidget = createWidget(widget.TEXT, {
      x: 0, y: 5, w: width, h: width,
      text_size: pl(36), color: COLORS.ON_SURFACE, text: "--:--",
      align_h: align.CENTER_H, char_space: 4,
      start_angle: -80, end_angle: 80
    });

    y += pl(60);

    // 2. Page Title "Settings"
    createWidget(widget.TEXT, {
      x: 0, y: y, w: width, h: pl(50),
      text: getText('measurement_settings'),
      text_size: pl(34), color: COLORS.ON_SURFACE, align_h: align.CENTER_H
    });
    y += pl(60);

    // 3. Card: 无感测量开关
    y = this.renderAutoSwitchCard(width, y);
    y += pl(20);

    // 4. Card: 每日测量时间（小时/分钟步进调节）
    y = this.renderWakeTimeCard(width, y);
    y += pl(20);

    // 5. 提示文案（markdown 渲染：无感测量说明 + 起床前设置建议）
    y = this.renderTipCard(width, y);
    y += pl(20);

    // 6. Card: About App
    y = this.renderAboutCard(width, y);
    y += pl(20);

    // 7. Card: Pulse Theory
    y = this.renderPulseTheoryCard(width, y);
    y += pl(20);

    // 8. Activation Status
    y = this.renderActivationCard(width, y);

    // Bottom padding
    createWidget(widget.TEXT, { x: 0, y: y, w: 10, h: pl(100), text: "" });
  },

  // --- Helper: Render Auto Switch Card ---
  renderAutoSwitchCard(width, y) {
    const cardHeight = pl(130);
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;

    // Card Background
    createWidget(widget.FILL_RECT, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(32), color: COLORS.SURFACE_CONTAINER
    });

    // Label
    createWidget(widget.TEXT, {
      x: cardX + pl(24), y: y - pl(25), w: cardWidth - pl(120), h: cardHeight,
      text: getText('silent_measure'),
      color: COLORS.ON_SURFACE, text_size: pl(30),
      align_h: align.LEFT, align_v: align.CENTER_V
    });

    mainSwitch = createWidget(widget.SLIDE_SWITCH, {
      x: cardX + cardWidth - pl(130), y: y + (cardHeight - pl(64)) / 2 + pl(20),
      w: pl(110), h: pl(80),
      select_bg: 'on.png', un_select_bg: 'off.png', slide_src: 'slide_button.png',
      slide_select_x: 40, slide_un_select_x: 8,
      checked: this.state.settings.isEnabled,
      disabled: !this.state.isActivated,
      checked_change_func: (slideSwitch, isEnabled) => {
        if (!this.state.isActivated) {
          showToast({ content: getText("virtual_data_toast") });
          slideSwitch.setProperty(prop.CHECKED, false);
          return;
        }
        this.state.settings.isEnabled = isEnabled;
        this.updateAlarm();
      }
    });

    return y + cardHeight;
  },

  // --- Helper: 每日测量时间卡（小时 ±1 / 分钟 ±15 步进，手表端免键盘）---
  renderWakeTimeCard(width, y) {
    const rowHeight = pl(100);
    const cardHeight = rowHeight * 2;
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;
    const btnW = pl(80), btnH = pl(70);

    createWidget(widget.FILL_RECT, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(32), color: COLORS.SURFACE_CONTAINER
    });

    // Row 1: 标签 + 当前时间
    createWidget(widget.TEXT, {
      x: cardX + pl(24), y: y, w: cardWidth - pl(200), h: rowHeight,
      text: getText('measure_time'),
      color: COLORS.ON_SURFACE, text_size: pl(30),
      align_h: align.LEFT, align_v: align.CENTER_V
    });
    wakeTimeText = createWidget(widget.TEXT, {
      x: cardX + cardWidth - pl(180), y: y, w: pl(160), h: rowHeight,
      text: fmtTime(this.state.settings.wakeHour, this.state.settings.wakeMinute),
      color: COLORS.PRIMARY, text_size: pl(38),
      align_h: align.CENTER_H, align_v: align.CENTER_V
    });

    // Divider
    createWidget(widget.FILL_RECT, {
      x: cardX + pl(20), y: y + rowHeight, w: cardWidth - pl(40), h: 2,
      color: COLORS.OUTLINE, alpha: 50
    });

    // Row 2: 四个步进按钮 [-1h] [+1h] [-15m] [+15m]
    const row2Y = y + rowHeight + (rowHeight - btnH) / 2;
    const gap = (cardWidth - btnW * 4) / 5;
    const mkBtn = (idx, label, dh, dm) => {
      createWidget(widget.BUTTON, {
        x: cardX + gap + (btnW + gap) * idx, y: row2Y, w: btnW, h: btnH,
        radius: pl(35),
        normal_color: COLORS.SURFACE_CONTAINER_HIGH, press_color: COLORS.PRIMARY,
        text: label, text_size: pl(24), color: COLORS.PRIMARY,
        click_func: () => this.adjustWakeTime(dh, dm)
      });
    };
    mkBtn(0, '-1h', -1, 0);
    mkBtn(1, '+1h', 1, 0);
    mkBtn(2, '-15m', 0, -15);
    mkBtn(3, '+15m', 0, 15);

    return y + cardHeight;
  },

  // 步进调整每日测量时间（24h 环回），已开启时立即重设闹钟
  adjustWakeTime(dh, dm) {
    const s = this.state.settings;
    let total = s.wakeHour * 60 + s.wakeMinute + dh * 60 + dm;
    total = ((total % 1440) + 1440) % 1440;
    s.wakeHour = Math.floor(total / 60);
    s.wakeMinute = total % 60;
    if (wakeTimeText) wakeTimeText.setProperty(prop.TEXT, fmtTime(s.wakeHour, s.wakeMinute));
    this.updateAlarm();
  },

  // --- Helper: 无感测量说明（markdown 渲染，含起床前设置建议）---
  renderTipCard(width, y) {
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;
    const pad = pl(24);
    const textW = cardWidth - pad * 2;
    const fontSize = pl(22);
    const content = getText('silent_measure_tip');

    // 先量高，画卡片底，再渲染 markdown
    const layout = buildMarkdownLayout(content, textW, fontSize);
    const cardHeight = layout.height + pad * 2;
    createWidget(widget.FILL_RECT, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(32), color: COLORS.SURFACE_CONTAINER
    });
    renderMarkdown({
      x: cardX + pad, y: y + pad, w: textW, h: layout.height + pl(20),
      content: content, fontSize: fontSize
    });

    return y + cardHeight;
  },

  // --- Helper: Render About Card ---
  renderAboutCard(width, y) {
    const cardHeight = pl(100);
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;

    createWidget(widget.BUTTON, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(32),
      normal_color: COLORS.SURFACE_CONTAINER, press_color: COLORS.SURFACE_CONTAINER_HIGH,
      text: getText('about_app'),
      text_size: pl(30), color: COLORS.ON_SURFACE,
      click_func: () => push({ url: "page/about" })
    });

    return y + cardHeight;
  },

  // --- Helper: Render Pulse Theory Card ---
  renderPulseTheoryCard(width, y) {
    const cardHeight = pl(100);
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;

    createWidget(widget.BUTTON, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(32),
      normal_color: COLORS.SURFACE_CONTAINER, press_color: COLORS.SURFACE_CONTAINER_HIGH,
      text: getText('pulse_theory'),
      text_size: pl(30), color: COLORS.PRIMARY,
      click_func: () => push({ url: "page/pulse_theory" })
    });

    return y + cardHeight;
  },

  // --- Helper: Render Activation Card ---
  renderActivationCard(width, y) {
    const cardHeight = pl(100);
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;

    let buttonText, buttonColor, clickFunc;

    if (this.state.isActivated) {
      // 已激活状态
      buttonText = getText('activated');
      buttonColor = COLORS.PRIMARY;
      clickFunc = null; // 禁用点击
    } else {
      // 未激活状态
      buttonText = getText('not_activated');
      buttonColor = COLORS.ERROR;
      clickFunc = () => {
        push({ url: 'page/activation_test' });
      };
    }

    const button = createWidget(widget.BUTTON, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(32),
      normal_color: COLORS.SURFACE_CONTAINER, press_color: COLORS.SURFACE_CONTAINER_HIGH,
      text: buttonText,
      text_size: pl(30),
      color: buttonColor,
      click_func: clickFunc
    });

    return y + cardHeight;
  },

  saveSettings() {
    Storage.patch(SETTINGS_FILE, { hrv: this.state.settings });
  },

  // 每日定时闹钟：到点唤醒 page/measurement 自动完成一次测量（store 持久化，重启不丢）
  updateAlarm() {
    this.saveSettings();
    if (this.state.alarmId > 0) {
      cancelAlarm({ id: this.state.alarmId });
      Storage.patch(SYSTEM_FILE, { alarm_id: null });
      this.state.alarmId = 0;
    }
    if (!this.state.settings.isEnabled) return;

    const alarmId = setAlarm({
      url: AUTO_MEASURE_PAGE_URL,
      time: nextOccurrenceTs(this.state.settings.wakeHour, this.state.settings.wakeMinute),
      repeat_type: REPEAT_DAY,
      store: true,
      param: AUTO_MEASURE_PARAM,
    });
    if (alarmId > 0) {
      this.state.alarmId = alarmId;
      Storage.patch(SYSTEM_FILE, { alarm_id: alarmId.toString() });
    } else {
      this.state.settings.isEnabled = false;
      this.saveSettings();
      if (mainSwitch) mainSwitch.setProperty(prop.CHECKED, false);
    }
  },

  onDestroy() {
    if (timeInterval) {
      clearInterval(timeInterval);
      timeInterval = null;
    }
    Storage.saveAndQuit();
  }
});

