/**
 * settings.js — 设置页（古风宣纸主题）
 *
 * 核心功能：无感测量 —— 用户设定一个每日时间（建议起床前 30~60 分钟），
 * 到点由系统闹钟自动唤醒 page/measurement 完成一次把脉，全程无需操作。
 *
 * 布局：固定宣纸背景（单图）+ 全屏 VIEW_CONTAINER 滚动（与 stress_UI2 一致）。
 * 提示文案用 buildMarkdownLayout 解析后在容器内自绘（古风深色文字覆盖原库暗底配色）。
 */

import { createWidget, widget, align, prop, text_style } from "@zos/ui";
import { set as setAlarm, cancel as cancelAlarm, REPEAT_DAY } from '@zos/alarm';
import { Storage } from '../utils/storage';
import { getDeviceInfo } from "@zos/device";
import { showToast } from '@zos/interaction';
import { push } from "@zos/router";
import { pw, ph, pl } from "../utils/zaui";
import { getText } from '@zos/i18n';
import { setStatusBarVisible } from '@zos/ui';
import { buildMarkdownLayout } from '../utils/markdown-renderer';

const SYSTEM_FILE = 'system.json';
const SETTINGS_FILE = 'settings.json';
// 闹钟唤醒测量页；param 由 app.js onCreate 接收，标记本次为无感自动测量
const AUTO_MEASURE_PAGE_URL = 'page/measurement';
const AUTO_MEASURE_PARAM = 'auto_measure';

// 古风宣纸配色（对齐 stress_UI2 / 项目统一视觉规范）
const C = {
  clock:    0x3A2A18,  // 顶部弧形时钟（深墨）
  title:    0x5A3A1A,  // 页面/卡片标题（深棕金）
  goldDeep: 0x8A5A20,  // 深金（大字时间、强调）
  gold:     0xF0B848,  // 亮金（主按钮底）
  text:     0x5A4632,  // 正文深棕
  body:     0x6A4A28,  // 次级正文
  sub:      0x9C8560,  // 弱化标签
  cardBg:   0xD8CCB2,  // 宣纸卡底（配 setAlpha(220) 毛玻璃）
  cardDeep: 0xC7B893,  // 深宣纸（步进按钮底/按钮常态）
  press:    0xB8A87F,  // 按压态
  sep:      0xC4B594,  // 分隔线
  danger:   0xA23B2E,  // 未激活（暗红，浅底可读）
};

// markdown 块类型 → 古风深色文字（宣纸浅底；原库配色为暗底设计，不可直用）
function mdColor(type) {
  switch (type) {
    case 'heading1':
    case 'heading2':
    case 'heading3': return C.goldDeep;
    case 'list':     return C.text;
    case 'blockquote': return C.sub;
    default:         return C.body;
  }
}

let mainSwitch;
let hourText, minuteText;
let timeTextWidget;
let timeInterval = null;

// 计算「今天/明天 HH:MM」的下一次触发时间（UTC 秒），供 @zos/alarm time 字段使用
function nextOccurrenceTs(hour, minute) {
  const now = new Date();
  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), hour, minute, 0);
  if (t.getTime() <= now.getTime()) t.setDate(t.getDate() + 1);
  return Math.floor(t.getTime() / 1000);
}

function pad2(n) {
  return n.toString().padStart(2, '0');
}

Page({
  state: {
    settings: {
      isEnabled: false,
      wakeHour: 7,     // 每日自动测量时间（默认 07:00）
      wakeMinute: 0,
    },
    alarmId: 0,
    isActivated: false,
    container: null,
  },

  onInit() {
    Storage.get(SETTINGS_FILE, (err, userSettings) => {
      if (userSettings && userSettings.hrv) {
        const s = userSettings.hrv;
        if (typeof s.isEnabled === 'boolean') this.state.settings.isEnabled = s.isEnabled;
        if (typeof s.wakeHour === 'number') this.state.settings.wakeHour = s.wakeHour;
        if (typeof s.wakeMinute === 'number') this.state.settings.wakeMinute = s.wakeMinute;
      }

      Storage.get(SYSTEM_FILE, (err, config) => {
        if (config) {
          if (config.alarm_id) this.state.alarmId = parseInt(config.alarm_id);
          this.state.isActivated = config.activation_status === 'activated';
        }

        this.build();
        this.startTimeTicker();
      });
    });
  },

  startTimeTicker() {
    if (timeInterval) clearInterval(timeInterval);
    const updateTime = () => {
      if (timeTextWidget) {
        const now = new Date();
        timeTextWidget.setProperty(prop.TEXT, `${pad2(now.getHours())}:${pad2(now.getMinutes())}`);
      }
    };
    updateTime();
    timeInterval = setInterval(updateTime, 1000);
  },

  build() {
    if (this._built) return;
    this._built = true;

    const { width, height } = getDeviceInfo();
    setStatusBarVisible(false);

    // 固定宣纸背景（单图一屏，不随内容滚动）
    createWidget(widget.IMG, { x: pw(0), y: ph(0), w: pl(480), h: pl(480), src: "Bg.png" });

    // 全屏滚动容器：所有内容控件挂在容器内
    const vc = createWidget(widget.VIEW_CONTAINER, { x: 0, y: 0, w: width, h: height, scroll_enable: 1 });
    this.state.container = vc;

    let y = pl(20);

    // 1. 顶部弧形时钟
    timeTextWidget = vc.createWidget(widget.TEXT, {
      x: 0, y: 5, w: width, h: width,
      text_size: pl(32), color: C.clock, text: "--:--",
      align_h: align.CENTER_H, char_space: 4,
      start_angle: -80, end_angle: 80
    });

    y += pl(60);

    // 2. 页面标题
    vc.createWidget(widget.TEXT, {
      x: 0, y: y, w: width, h: pl(50),
      text: getText('measurement_settings'),
      text_size: pl(34), color: C.title, align_h: align.CENTER_H
    });
    y += pl(64);

    // 3. 无感测量开关卡
    y = this.renderAutoSwitchCard(vc, width, y);
    y += pl(18);

    // 4. 每日测量时间卡（双列步进时间选择器）
    y = this.renderWakeTimeCard(vc, width, y);
    y += pl(18);

    // 5. 提示文案卡（markdown 自绘：无感测量说明 + 起床前设置建议）
    y = this.renderTipCard(vc, width, y);
    y += pl(18);

    // 6. 关于应用
    y = this.renderNavButton(vc, width, y, getText('about_app'), C.text, () => push({ url: "page/about" }));
    y += pl(14);

    // 7. 脉象原理
    y = this.renderNavButton(vc, width, y, getText('pulse_theory'), C.goldDeep, () => push({ url: "page/pulse_theory" }));
    y += pl(14);

    // 8. 激活状态
    y = this.renderActivationCard(vc, width, y);

    // 底部留白（撑出容器滚动余量）
    vc.createWidget(widget.FILL_RECT, { x: 0, y: y, w: width, h: pl(50), color: 0x000000 }).setAlpha(0);
  },

  // --- 无感测量开关卡（宣纸毛玻璃）---
  renderAutoSwitchCard(vc, width, y) {
    const cardHeight = pl(130);
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;

    vc.createWidget(widget.FILL_RECT, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(24), color: C.cardBg
    }).setAlpha(220);

    vc.createWidget(widget.TEXT, {
      x: cardX + pl(24), y: y - pl(25), w: cardWidth - pl(120), h: cardHeight,
      text: getText('silent_measure'),
      color: C.title, text_size: pl(30),
      align_h: align.LEFT, align_v: align.CENTER_V
    });

    mainSwitch = vc.createWidget(widget.SLIDE_SWITCH, {
      x: cardX + cardWidth - pl(130), y: y + (cardHeight - pl(64)) / 2 + pl(20),
      w: pl(110), h: pl(80),
      select_bg: 'on.png', un_select_bg: 'off.png', slide_src: 'slide_button.png',
      slide_select_x: 40, slide_un_select_x: 8,
      checked: this.state.settings.isEnabled,
      disabled: !this.state.isActivated,
      checked_change_func: (slideSwitch, isEnabled) => {
        if (!this.state.isActivated) {
          showToast({ content: getText("virtual_data_toast") });
          slideSwitch.setProperty(prop.CHECKED, false);
          return;
        }
        this.state.settings.isEnabled = isEnabled;
        this.updateAlarm();
      }
    });

    return y + cardHeight;
  },

  // --- 每日测量时间卡：双列步进选择器 ---
  // 布局：标签行 → [＋][＋] / [HH]:[MM] / [－][－]，列即所调数位，直觉对应
  // 步进：小时 ±1，分钟 ±15
  renderWakeTimeCard(vc, width, y) {
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;
    const colW = pl(120), btnH = pl(56), valH = pl(80);
    const titleH = pl(56);
    const cardHeight = titleH + btnH + valH + btnH + pl(24);

    vc.createWidget(widget.FILL_RECT, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(24), color: C.cardBg
    }).setAlpha(220);

    // 标签
    vc.createWidget(widget.TEXT, {
      x: cardX + pl(24), y: y + pl(16), w: cardWidth - pl(48), h: pl(32),
      text: getText('measure_time'),
      color: C.sub, text_size: pl(24),
      align_h: align.LEFT
    });

    // 两列位置：小时列 / 分钟列，中间冒号
    const gapHalf = pl(22);
    const hourX = cardX + cardWidth / 2 - gapHalf - colW;
    const minX = cardX + cardWidth / 2 + gapHalf;
    const plusY = y + titleH;
    const valY = plusY + btnH + pl(4);
    const minusY = valY + valH + pl(4);

    const s = this.state.settings;
    const mkStepBtn = (bx, by, label, dh, dm) => {
      vc.createWidget(widget.BUTTON, {
        x: bx, y: by, w: colW, h: btnH, radius: pl(28),
        normal_color: C.cardDeep, press_color: C.gold,
        text: label, text_size: pl(34), color: C.title,
        click_func: () => this.adjustWakeTime(dh, dm)
      });
    };

    // 小时列：+1h / 07 / -1h
    mkStepBtn(hourX, plusY, '+', 1, 0);
    hourText = vc.createWidget(widget.TEXT, {
      x: hourX, y: valY, w: colW, h: valH,
      text: pad2(s.wakeHour), text_size: pl(58), color: C.goldDeep,
      align_h: align.CENTER_H, align_v: align.CENTER_V
    });
    mkStepBtn(hourX, minusY, '−', -1, 0);

    // 冒号
    vc.createWidget(widget.TEXT, {
      x: cardX + cardWidth / 2 - gapHalf, y: valY, w: gapHalf * 2, h: valH,
      text: ':', text_size: pl(50), color: C.goldDeep,
      align_h: align.CENTER_H, align_v: align.CENTER_V
    });

    // 分钟列：+15m / 00 / -15m
    mkStepBtn(minX, plusY, '+', 0, 15);
    minuteText = vc.createWidget(widget.TEXT, {
      x: minX, y: valY, w: colW, h: valH,
      text: pad2(s.wakeMinute), text_size: pl(58), color: C.goldDeep,
      align_h: align.CENTER_H, align_v: align.CENTER_V
    });
    mkStepBtn(minX, minusY, '−', 0, -15);

    return y + cardHeight;
  },

  // 步进调整每日测量时间（24h 环回），已开启时立即重设闹钟
  adjustWakeTime(dh, dm) {
    const s = this.state.settings;
    let total = s.wakeHour * 60 + s.wakeMinute + dh * 60 + dm;
    total = ((total % 1440) + 1440) % 1440;
    s.wakeHour = Math.floor(total / 60);
    s.wakeMinute = total % 60;
    if (hourText) hourText.setProperty(prop.TEXT, pad2(s.wakeHour));
    if (minuteText) minuteText.setProperty(prop.TEXT, pad2(s.wakeMinute));
    this.updateAlarm();
  },

  // --- 无感测量说明卡（markdown 容器内自绘，古风深色文字）---
  renderTipCard(vc, width, y) {
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;
    const pad = pl(24);
    const textW = cardWidth - pad * 2;
    const fontSize = pl(22);
    const content = getText('silent_measure_tip');

    const layout = buildMarkdownLayout(content, textW, fontSize);
    const cardHeight = layout.height + pad * 2;
    vc.createWidget(widget.FILL_RECT, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(24), color: C.cardBg
    }).setAlpha(220);

    layout.items.forEach((item) => {
      vc.createWidget(widget.TEXT, {
        x: cardX + pad, y: y + pad + item.offset, w: textW, h: item.height,
        text: item.text, text_size: item.style.size,
        color: mdColor(item.type),
        align_h: align.LEFT,
        text_style: (item.type === 'heading1' || item.type === 'heading2' || item.type === 'heading3')
          ? (text_style.WRAP | text_style.BOLD)
          : text_style.WRAP
      });
    });

    return y + cardHeight;
  },

  // --- 通用导航按钮（宣纸底全宽圆角）---
  renderNavButton(vc, width, y, label, textColor, clickFunc) {
    const cardHeight = pl(96);
    const cardWidth = pl(390);
    const cardX = (width - cardWidth) / 2;

    vc.createWidget(widget.BUTTON, {
      x: cardX, y: y, w: cardWidth, h: cardHeight,
      radius: pl(48),
      normal_color: C.cardBg, press_color: C.press,
      text: label, text_size: pl(30), color: textColor,
      click_func: clickFunc
    });

    return y + cardHeight;
  },

  // --- 激活状态卡 ---
  renderActivationCard(vc, width, y) {
    if (this.state.isActivated) {
      // 已激活：静态展示，深金文字
      return this.renderNavButton(vc, width, y, getText('activated'), C.goldDeep, null);
    }
    // 未激活：暗红提示，点击进入激活页
    return this.renderNavButton(vc, width, y, getText('not_activated'), C.danger, () => {
      push({ url: 'page/activation_test' });
    });
  },

  saveSettings() {
    Storage.patch(SETTINGS_FILE, { hrv: this.state.settings });
  },

  // 每日定时闹钟：到点唤醒 page/measurement 自动完成一次测量（store 持久化，重启不丢）
  updateAlarm() {
    this.saveSettings();
    if (this.state.alarmId > 0) {
      cancelAlarm({ id: this.state.alarmId });
      Storage.patch(SYSTEM_FILE, { alarm_id: null });
      this.state.alarmId = 0;
    }
    if (!this.state.settings.isEnabled) return;

    const alarmId = setAlarm({
      url: AUTO_MEASURE_PAGE_URL,
      time: nextOccurrenceTs(this.state.settings.wakeHour, this.state.settings.wakeMinute),
      repeat_type: REPEAT_DAY,
      store: true,
      param: AUTO_MEASURE_PARAM,
    });
    if (alarmId > 0) {
      this.state.alarmId = alarmId;
      Storage.patch(SYSTEM_FILE, { alarm_id: alarmId.toString() });
    } else {
      this.state.settings.isEnabled = false;
      this.saveSettings();
      if (mainSwitch) mainSwitch.setProperty(prop.CHECKED, false);
    }
  },

  onDestroy() {
    if (timeInterval) {
      clearInterval(timeInterval);
      timeInterval = null;
    }
    this._built = false;
    Storage.saveAndQuit();
  }
});

