// --- 每日测量时间卡：展示当前时间，点击进入官方 PICKER 选择页 ---
renderWakeTimeCard(vc, width, y) {
  const cardWidth = pl(390);
  const cardX = (width - cardWidth) / 2;
  const cardHeight = pl(150);

  const bg = vc.createWidget(widget.FILL_RECT, {
    x: cardX, y: y, w: cardWidth, h: cardHeight,
    radius: pl(24), color: C.cardBg
  });
  bg.setAlpha(220);

  // 标签 + 修改提示（右侧金色箭头暗示可点）
  vc.createWidget(widget.TEXT, {
    x: cardX + pl(24), y: y + pl(16), w: cardWidth - pl(140), h: pl(32),
    text: getText('measure_time'),
    color: C.sub, text_size: pl(24),
    align_h: align.LEFT
  });
  vc.createWidget(widget.TEXT, {
    x: cardX + cardWidth - pl(130), y: y + pl(16), w: pl(106), h: pl(32),
    text: getText('view_detail') + ' >',
    color: 0xB8860B, text_size: pl(22),
    align_h: align.RIGHT
  });

  // 当前时间（深金大字居中）
  const s = this.state.settings;
  wakeTimeText = vc.createWidget(widget.TEXT, {
    x: cardX, y: y + pl(52), w: cardWidth, h: pl(80),
    text: pad2(s.wakeHour) + ':' + pad2(s.wakeMinute),
    text_size: pl(58), color: C.goldDeep,
    align_h: align.CENTER_H, align_v: align.CENTER_V
  });

  // 整卡可点：进入全屏时间选择页（WIDGET_PICKER）
  bg.addEventListener(event.CLICK_UP, () => {
    push({ url: 'page/time_picker' });
  });

  return y + cardHeight;
},

// 选择页内已完成保存与闹钟重设；返回本页时回读刷新显示
onShow() {
  if (!this._built) return;
  Storage.get(SETTINGS_FILE, (err, userSettings) => {
    if (userSettings && userSettings.hrv) {
      const s = userSettings.hrv;
      if (typeof s.wakeHour === 'number') this.state.settings.wakeHour = s.wakeHour;
      if (typeof s.wakeMinute === 'number') this.state.settings.wakeMinute = s.wakeMinute;
      if (wakeTimeText) {
        wakeTimeText.setProperty(prop.TEXT, pad2(this.state.settings.wakeHour) + ':' + pad2(this.state.settings.wakeMinute));
      }
    }
    Storage.get(SYSTEM_FILE, (err, config) => {
      if (config && config.alarm_id) this.state.alarmId = parseInt(config.alarm_id);
    });
  });
},

