// --- 每日测量时间卡：双列步进选择器 ---
// 布局：标签行 → [＋][＋] / [HH]:[MM] / [－][－]，列即所调数位，直觉对应
// 步进：小时 ±1，分钟 ±15
renderWakeTimeCard(vc, width, y) {
  const cardWidth = pl(390);
  const cardX = (width - cardWidth) / 2;
  const colW = pl(120), btnH = pl(56), valH = pl(80);
  const titleH = pl(56);
  const cardHeight = titleH + btnH + valH + btnH + pl(24);

  vc.createWidget(widget.FILL_RECT, {
    x: cardX, y: y, w: cardWidth, h: cardHeight,
    radius: pl(24), color: C.cardBg
  }).setAlpha(220);

  // 标签
  vc.createWidget(widget.TEXT, {
    x: cardX + pl(24), y: y + pl(16), w: cardWidth - pl(48), h: pl(32),
    text: getText('measure_time'),
    color: C.sub, text_size: pl(24),
    align_h: align.LEFT
  });

  // 两列位置：小时列 / 分钟列，中间冒号
  const gapHalf = pl(22);
  const hourX = cardX + cardWidth / 2 - gapHalf - colW;
  const minX = cardX + cardWidth / 2 + gapHalf;
  const plusY = y + titleH;
  const valY = plusY + btnH + pl(4);
  const minusY = valY + valH + pl(4);

  const s = this.state.settings;
  const mkStepBtn = (bx, by, label, dh, dm) => {
    vc.createWidget(widget.BUTTON, {
      x: bx, y: by, w: colW, h: btnH, radius: pl(28),
      normal_color: C.cardDeep, press_color: C.gold,
      text: label, text_size: pl(34), color: C.title,
      click_func: () => this.adjustWakeTime(dh, dm)
    });
  };

  // 小时列：+1h / 07 / -1h
  mkStepBtn(hourX, plusY, '+', 1, 0);
  hourText = vc.createWidget(widget.TEXT, {
    x: hourX, y: valY, w: colW, h: valH,
    text: pad2(s.wakeHour), text_size: pl(58), color: C.goldDeep,
    align_h: align.CENTER_H, align_v: align.CENTER_V
  });
  mkStepBtn(hourX, minusY, '-', -1, 0);

  // 冒号
  vc.createWidget(widget.TEXT, {
    x: cardX + cardWidth / 2 - gapHalf, y: valY, w: gapHalf * 2, h: valH,
    text: ':', text_size: pl(50), color: C.goldDeep,
    align_h: align.CENTER_H, align_v: align.CENTER_V
  });

  // 分钟列：+15m / 00 / -15m
  mkStepBtn(minX, plusY, '+', 0, 15);
  minuteText = vc.createWidget(widget.TEXT, {
    x: minX, y: valY, w: colW, h: valH,
    text: pad2(s.wakeMinute), text_size: pl(58), color: C.goldDeep,
    align_h: align.CENTER_H, align_v: align.CENTER_V
  });
  mkStepBtn(minX, minusY, '-', 0, -15);

  return y + cardHeight;
},

// 步进调整每日测量时间（24h 环回），已开启时立即重设闹钟
adjustWakeTime(dh, dm) {
  const s = this.state.settings;
  let total = s.wakeHour * 60 + s.wakeMinute + dh * 60 + dm;
  total = ((total % 1440) + 1440) % 1440;
  s.wakeHour = Math.floor(total / 60);
  s.wakeMinute = total % 60;
  if (hourText) hourText.setProperty(prop.TEXT, pad2(s.wakeHour));
  if (minuteText) minuteText.setProperty(prop.TEXT, pad2(s.wakeMinute));
  this.updateAlarm();
},

