    picker_cb: function (picker, event_type, column_index, select_index) {
      // 事件语义：0=列失焦 1=列聚焦 2=列选中（滚动定值与点击 ✓ 均触发）
      // 聚焦/失焦说明用户仍在操作（如切列），取消待执行的自动返回
      if (event_type === 0 || event_type === 1) {
        self._cancelAutoBack();
        return;
      }
      if (event_type !== 2) return;

      if (column_index === 0) self.state.hrv.wakeHour = select_index;
      else if (column_index === 1) self.state.hrv.wakeMinute = select_index * MINUTE_STEP;
      self.saveAndReschedule();

      // 副标题即时回显新值，明确"已保存"
      picker.setProperty(prop.SUBTITLE, pad2(self.state.hrv.wakeHour) + ':' + pad2(self.state.hrv.wakeMinute));

      // 选中即视为可完成：短暂停留后自动返回设置页；
      // 若用户继续滚动/切列（触发 0/1/2 事件），计时器被重置或取消，不会误退
      self._scheduleAutoBack();
    },
  });
},

// --- 自动返回：延时退回设置页，任何后续操作都会重置/取消 ---
_scheduleAutoBack() {
  this._cancelAutoBack();
  this._backTimer = setTimeout(function () { back(); }, 1200);
},

_cancelAutoBack() {
  if (this._backTimer) {
    clearTimeout(this._backTimer);
    this._backTimer = null;
  }
},

