    picker_cb: function (picker, event_type, column_index, select_index) {
      try {
        // 事件语义：0=列失焦 1=列聚焦 2=列选中
        // ✓ 完成键按下时焦点列会失焦（事件0）且不再有新列聚焦；
        // 手动切列则是 0 后立刻跟 1 —— 以此区分「完成」与「继续编辑」
        if (event_type === 1) {
          self._cancelAutoBack();
          return;
        }
        if (event_type === 0) {
          self._scheduleAutoBack();
          return;
        }
        if (event_type !== 2) return;

        // 选中即保存（滚动定值与 ✓ 均会触发）；loop 模式下索引取模防越界
        if (column_index === 0) {
          self.state.hrv.wakeHour = ((select_index % 24) + 24) % 24;
        } else if (column_index === 1) {
          var mCount = 60 / MINUTE_STEP;
          self.state.hrv.wakeMinute = (((select_index % mCount) + mCount) % mCount) * MINUTE_STEP;
        }
        self.saveAndReschedule();

        // 副标题即时回显新值，明确"已保存"
        picker.setProperty(prop.SUBTITLE, pad2(self.state.hrv.wakeHour) + ':' + pad2(self.state.hrv.wakeMinute));
      } catch (e) {
        logger.error('picker_cb error: ' + e);
      }
    },
  });
},

// --- 完成返回：失焦后短延时退回设置页；若紧跟聚焦事件（切列）则取消 ---
_scheduleAutoBack() {
  this._cancelAutoBack();
  this._backTimer = setTimeout(function () { back(); }, 300);
},

_cancelAutoBack() {
  if (this._backTimer) {
    clearTimeout(this._backTimer);
    this._backTimer = null;
  }
},

