/**
 * time_picker.js — 无感测量时间选择页（自制控件，古风宣纸主题）
 *
 * 弃用官方 WIDGET_PICKER（回调行为不可靠）。
 * 布局：标题 + 双列大字步进器（时 ±1 / 分 ±5，24h/60m 环回）+ 底部「确定」。
 * 保存语义明确：点「确定」→ 写 settings.json + 重设每日闹钟 + 返回设置页；
 * 侧滑返回 = 取消，不改动任何已存配置。
 *
 * API_LEVEL: 3.0+
 */

import { createWidget, widget, align, prop } from '@zos/ui';
import { set as setAlarm, cancel as cancelAlarm, REPEAT_DAY } from '@zos/alarm';
import { back } from '@zos/router';
import { getDeviceInfo } from '@zos/device';
import { Storage } from '../utils/storage';
import { getText } from '@zos/i18n';
import { setStatusBarVisible } from '@zos/ui';
import { pw, ph, pl } from '../utils/zaui';

const SYSTEM_FILE = 'system.json';
const SETTINGS_FILE = 'settings.json';
const AUTO_MEASURE_PAGE_URL = 'page/measurement';
const AUTO_MEASURE_PARAM = 'auto_measure';

const MINUTE_STEP = 5;

// 古风宣纸配色（对齐 settings/stress_UI2）
const C = {
  title:    0x5A3A1A,  // 标题深棕金
  goldDeep: 0x8A5A20,  // 大字时间深金
  gold:     0xF0B848,  // 主按钮亮金
  sub:      0x9C8560,  // 弱化提示
  btnBg:    0xC7B893,  // 步进按钮深宣纸
  btnPress: 0xB8A87F,  // 按压态
};

function pad2(n) {
  return n.toString().padStart(2, '0');
}

// 计算「今天/明天 HH:MM」的下一次触发时间（UTC 秒）
function nextOccurrenceTs(hour, minute) {
  var now = new Date();
  var t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), hour, minute, 0);
  if (t.getTime() <= now.getTime()) t.setDate(t.getDate() + 1);
  return Math.floor(t.getTime() / 1000);
}

Page({
  state: {
    hrv: { isEnabled: false, wakeHour: 7, wakeMinute: 0 },
    alarmId: 0,
    hourText: null,
    minuteText: null,
  },

  onInit() {
    Storage.get(SETTINGS_FILE, (err, userSettings) => {
      if (userSettings && userSettings.hrv) {
        var s = userSettings.hrv;
        if (typeof s.isEnabled === 'boolean') this.state.hrv.isEnabled = s.isEnabled;
        if (typeof s.wakeHour === 'number') this.state.hrv.wakeHour = s.wakeHour;
        if (typeof s.wakeMinute === 'number') this.state.hrv.wakeMinute = s.wakeMinute;
      }
      Storage.get(SYSTEM_FILE, (err, config) => {
        if (config && config.alarm_id) this.state.alarmId = parseInt(config.alarm_id);
        this.build();
      });
    });
  },

  build() {
    if (this._built) return;
    this._built = true;
    setStatusBarVisible(false);

    var dev = getDeviceInfo();
    var W = dev.width, H = dev.height;
    var self = this;

    // 宣纸背景
    createWidget(widget.IMG, { x: pw(0), y: ph(0), w: pl(480), h: pl(480), src: 'Bg.png' });

    // 标题
    createWidget(widget.TEXT, {
      x: 0, y: pl(36), w: W, h: pl(44),
      text: getText('measure_time'), text_size: pl(32), color: C.title,
      align_h: align.CENTER_H,
    });

    // 双列步进器几何：列宽 130，列间为冒号留 44
    var colW = pl(130), btnH = pl(64), valH = pl(96);
    var hourX = Math.round(W / 2) - pl(22) - colW;
    var minX = Math.round(W / 2) + pl(22);
    var plusY = pl(104);
    var valY = plusY + btnH + pl(8);
    var minusY = valY + valH + pl(8);

    // 步进按钮工厂（dh 小时增量 / dm 分钟增量）
    var mkBtn = function (bx, label, dh, dm) {
      createWidget(widget.BUTTON, {
        x: bx, y: dh !== 0 || dm > 0 ? plusY : minusY, w: colW, h: btnH, radius: pl(32),
        normal_color: C.btnBg, press_color: C.btnPress,
        text: label, text_size: pl(40), color: C.title,
        click_func: function () { self.adjust(dh, dm); },
      });
    };

    // 小时列
    createWidget(widget.BUTTON, {
      x: hourX, y: plusY, w: colW, h: btnH, radius: pl(32),
      normal_color: C.btnBg, press_color: C.btnPress,
      text: '+', text_size: pl(40), color: C.title,
      click_func: function () { self.adjust(1, 0); },
    });
    this.state.hourText = createWidget(widget.TEXT, {
      x: hourX, y: valY, w: colW, h: valH,
      text: pad2(this.state.hrv.wakeHour), text_size: pl(76), color: C.goldDeep,
      align_h: align.CENTER_H, align_v: align.CENTER_V,
    });
    createWidget(widget.BUTTON, {
      x: hourX, y: minusY, w: colW, h: btnH, radius: pl(32),
      normal_color: C.btnBg, press_color: C.btnPress,
      text: '-', text_size: pl(40), color: C.title,
      click_func: function () { self.adjust(-1, 0); },
    });

    // 冒号
    createWidget(widget.TEXT, {
      x: hourX + colW, y: valY, w: minX - hourX - colW, h: valH,
      text: ':', text_size: pl(60), color: C.goldDeep,
      align_h: align.CENTER_H, align_v: align.CENTER_V,
    });

    // 分钟列
    createWidget(widget.BUTTON, {
      x: minX, y: plusY, w: colW, h: btnH, radius: pl(32),
      normal_color: C.btnBg, press_color: C.btnPress,
      text: '+', text_size: pl(40), color: C.title,
      click_func: function () { self.adjust(0, MINUTE_STEP); },
    });
    this.state.minuteText = createWidget(widget.TEXT, {
      x: minX, y: valY, w: colW, h: valH,
      text: pad2(this.state.hrv.wakeMinute), text_size: pl(76), color: C.goldDeep,
      align_h: align.CENTER_H, align_v: align.CENTER_V,
    });
    createWidget(widget.BUTTON, {
      x: minX, y: minusY, w: colW, h: btnH, radius: pl(32),
      normal_color: C.btnBg, press_color: C.btnPress,
      text: '-', text_size: pl(40), color: C.title,
      click_func: function () { self.adjust(0, -MINUTE_STEP); },
    });

    // 步进说明（弱化小字）
    createWidget(widget.TEXT, {
      x: 0, y: minusY + btnH + pl(10), w: W, h: pl(28),
      text: '±1h / ±' + MINUTE_STEP + 'min', text_size: pl(20), color: C.sub,
      align_h: align.CENTER_H,
    });

    // 底部「确定」：保存 + 重设闹钟 + 返回
    createWidget(widget.BUTTON, {
      x: Math.round((W - pl(320)) / 2), y: H - pl(116), w: pl(320), h: pl(84), radius: pl(42),
      normal_color: C.gold, press_color: 0xC89A38,
      text: getText('confirm'), text_size: pl(32), color: 0x1A1206,
      click_func: function () {
        self.saveAndReschedule();
        back();
      },
    });
  },

  // 步进调整（分钟进位到小时，24h 环回），仅更新显示，不落盘
  adjust(dh, dm) {
    var s = this.state.hrv;
    var total = s.wakeHour * 60 + s.wakeMinute + dh * 60 + dm;
    total = ((total % 1440) + 1440) % 1440;
    s.wakeHour = Math.floor(total / 60);
    s.wakeMinute = total % 60;
    if (this.state.hourText) this.state.hourText.setProperty(prop.TEXT, pad2(s.wakeHour));
    if (this.state.minuteText) this.state.minuteText.setProperty(prop.TEXT, pad2(s.wakeMinute));
  },

  saveAndReschedule() {
    Storage.patch(SETTINGS_FILE, { hrv: this.state.hrv });

    // 未开启无感测量时只存时间，不动闹钟
    if (!this.state.hrv.isEnabled) return;

    if (this.state.alarmId > 0) {
      cancelAlarm({ id: this.state.alarmId });
      this.state.alarmId = 0;
    }
    var alarmId = setAlarm({
      url: AUTO_MEASURE_PAGE_URL,
      time: nextOccurrenceTs(this.state.hrv.wakeHour, this.state.hrv.wakeMinute),
      repeat_type: REPEAT_DAY,
      store: true,
      param: AUTO_MEASURE_PARAM,
    });
    if (alarmId > 0) {
      this.state.alarmId = alarmId;
      Storage.patch(SYSTEM_FILE, { alarm_id: alarmId.toString() });
    }
  },

  onDestroy() {
    this._built = false;
    Storage.saveAndQuit();
  },
});

